import {fleetSelection,parseTargetReleases,fleetCapable} from './fleet-selection.js';
export {fleetCapable};
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function fleetFields(){return `<details class="allocation-fields"><summary>服务器调度范围</summary><label>选机方式<select name="route-mode"><option value="fixed">当前工作台服务器</option><option value="auto">在指定候选服务器中自动选择空位</option></select></label><div id="fleet-options" hidden><fieldset><legend>候选服务器（主动选择）</legend><div id="fleet-candidates"></div><button type="button" class="button" id="fleet-all">选择全部已授权服务器</button></fieldset><label>每节点固定项目版本（可选）<textarea name="target-releases" rows="3" placeholder="gpu-1=完整64位release&#10;gpu-2=完整64位release" spellcheck="false"></textarea></label><p class="muted">使用当前项目名和已选固定版本；此映射可覆盖各节点不同的 READY release。数据集名称、版本和命令保持完全一致。未就绪节点不会承接训练；不自动复制项目、环境或数据。</p><p id="fleet-form-status" class="form-error" role="status"></p></div></details>`;}
export function fleetCandidateHTML(machines,selected=[]){return machines.map(m=>`<label class="fleet-candidate"><input type="checkbox" name="candidate-host" value="${esc(m.id)}" ${selected.includes(m.id)?'checked':''}> ${esc(m.id)} · ${esc(m.cards)} 张</label>`).join('');}
export function fleetFromForm(form,machines){if(form.get('route-mode')!=='auto')return null;return {machine:'auto',...fleetSelection(form.getAll('candidate-host'),parseTargetReleases(String(form.get('target-releases')||'').trim().split(/\s+/).filter(Boolean)),machines.map(m=>m.id))};}
export function candidateHostsFromDOM(section,store){return [...section.querySelectorAll('[name=candidate-host]:checked')].map(n=>store.data?.gpuq?.hosts?.find(h=>h.id===n.value)).filter(Boolean);}
